const paymentTotals = `-- name: PaymentTotals :many
SELECT payment_method,
       COALESCE(sum(amount) FILTER (WHERE payment_type = 'PAYMENT'), 0)::numeric AS paid,
       COALESCE(sum(amount) FILTER (WHERE payment_type = 'REFUND'), 0)::numeric AS refunded
FROM payments
WHERE tenant_id = $1 AND property_id = $2 AND business_date = $3 AND status = 'POSTED'
GROUP BY payment_method
ORDER BY payment_method
`

type PaymentTotalsParams struct {
	TenantID     int64
	PropertyID   int64
	BusinessDate civil.Date
}

type PaymentTotalsRow struct {
	PaymentMethod string
	Paid          decimal.Decimal
	Refunded      decimal.Decimal
}

// Net cash by method for a business date: payments minus refunds, voided payments excluded.
func (q *Queries) PaymentTotals(ctx context.Context, arg PaymentTotalsParams) ([]PaymentTotalsRow, error) {
	rows, err := q.db.Query(ctx, paymentTotals, arg.TenantID, arg.PropertyID, arg.BusinessDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PaymentTotalsRow{}
	for rows.Next() {
		var i PaymentTotalsRow
		if err := rows.Scan(&i.PaymentMethod, &i.Paid, &i.Refunded); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sumRefundsOf = `-- name: SumRefundsOf :one
SELECT COALESCE(sum(amount), 0)::numeric AS refunded, count(*)::int AS refund_count
FROM payments WHERE property_id = $1 AND refund_of_payment_id = $2 AND status = 'POSTED'
`

type SumRefundsOfParams struct {
	PropertyID int64
	PaymentID  *int64
}

type SumRefundsOfRow struct {
	Refunded    decimal.Decimal
	RefundCount int32
}

// Refunds of a payment that were not voided (REFUND payments cannot be voided, so all of them count).
func (q *Queries) SumRefundsOf(ctx context.Context, arg SumRefundsOfParams) (SumRefundsOfRow, error) {
	row := q.db.QueryRow(ctx, sumRefundsOf, arg.PropertyID, arg.PaymentID)
	var i SumRefundsOfRow
	err := row.Scan(&i.Refunded, &i.RefundCount)
	return i, err
}

